    int n = 4, c = 0;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++) c++;
    printf("%d\n", c);
    return 0;
}

#include <stdio.h>
int main(void) {
    int n = 64, c = 0;
    while (n > 1) { n = n / 2; c++; }
    printf("%d\n", c);
    return 0;
}

