#include <stdio.h>
int main(void) {
    int n = 16, c = 0;
    for (int i = 0; i < n; i++)
        for (int j = 1; j <= n; j *= 2) c++;
    printf("%d\n", c);
    return 0;
}

#include <stdio.h>
int main(void) {
    int n = 100, c = 0;
    while (n > 1) { n /= 2; c++; }
    printf("%d\n", c);
    return 0;
}
